    private void jTextField2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jTextField2ActionPerformed
    String numeroEjercicio = jTextField2.getText().trim();
    String nombreRutina = jTextField1.getText().trim();
    
    String nombreEjercicioStr = "";
    
    switch (numeroEjercicio) {
        case "1": nombreEjercicioStr = "Sentadilla"; break;
        case "2": nombreEjercicioStr = "Press de Banca"; break;
        case "3": nombreEjercicioStr = "Dominadas"; break;
        case "4": nombreEjercicioStr = "Curl de Bíceps"; break;
        case "5": nombreEjercicioStr = "Zancadas / Lunges"; break;
        case "6": nombreEjercicioStr = "Press Militar"; break;
        case "7": nombreEjercicioStr = "Extensiones de Tríceps"; break;
        case "8": nombreEjercicioStr = "Peso Muerto"; break;
        case "9": nombreEjercicioStr = "Remo con Barra"; break;
        case "10": nombreEjercicioStr = "Aperturas con Mancuernas"; break;
        default: nombreEjercicioStr = "Desconocido"; break;
    }
    
    //Muestra el mensaje en el primer cuadro
    jTextArea1.setText("¡Ejercicio \"" + nombreEjercicioStr + "\" agregado a la rutina!");
    
    //Muestra el resumen en el segundo cuadro 
    jTextArea2.setText("Resumen de la rutina creada:\n- Nombre: " + nombreRutina + "\n- Ejercicios seleccionados: " + nombreEjercicioStr);

    }//GEN-LAST:event_jTextField2ActionPerformed

    private void jTextField3ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jTextField3ActionPerformed
        String respuesta = jTextField3.getText().trim();
    
    if (respuesta.equalsIgnoreCase("Si") || respuesta.equalsIgnoreCase("Sí")) {
        //Muestra el mensaje de éxito en el tercer cuadro
        jTextArea3.setText("¡Se ha generado correctamente el archivo de su rutina!");
    } else {
        jTextArea3.setText("Operación cancelada. No se exportó la rutina.");
    }

    }//GEN-LAST:event_jTextField3ActionPerformed

    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        // Preguntamos si realmente desea salir de la sección
    int opcion = javax.swing.JOptionPane.showConfirmDialog(this, 
        "¿Estás seguro que deseas salir de esta sección?", 
        "Salir", 
        javax.swing.JOptionPane.YES_NO_OPTION);
        
    if (opcion == javax.swing.JOptionPane.YES_OPTION) {
        this.dispose(); // Cierra esta ventana y regresa al menú principal
    }

    }//GEN-LAST:event_jButton1ActionPerformed

    
